-- Karten-NPCs werden echte Welt-NPCs und hängen an ihrem Gebäude.
-- Stadtsimulations-Attribute nur, wenn for_city_simulation true ist.

alter table public.locations
  add column if not exists map_building_id text;

create unique index if not exists locations_map_building_id_uidx
  on public.locations (map_building_id);

alter table public.npcs
  add column if not exists aurenfurt_catalog_id text;

create unique index if not exists npcs_aurenfurt_catalog_id_uidx
  on public.npcs (aurenfurt_catalog_id);

with seed as (
  select $aurenfurt${"buildings":[{"slug":"goldkuppel","name":"Goldene Kuppel","type":"Palast","description":"Thronsaal unter der Kuppel. Jeder Bogen hat eine Wache, jeder Flur ein Protokoll.","parent_id":"c1afce7e-5c4b-4fef-8654-818ef0534993","u":0.5,"v":0.47,"district_id":"palast"},{"slug":"hofwache","name":"Hofwache der Stadtwachen","type":"Wache","description":"Wachstube am inneren Ring. Hier meldet die Garde dem Hof, und Willkür trägt ein Siegel.","parent_id":"c1afce7e-5c4b-4fef-8654-818ef0534993","u":0.46,"v":0.52,"district_id":"palast"},{"slug":"hofkanzlei","name":"Hofkanzlei","type":"Kontor","description":"Akten, Siegel und stille Türen. Wer hier schreibt, formt die Stadt, bevor sie es merkt.","parent_id":"c1afce7e-5c4b-4fef-8654-818ef0534993","u":0.54,"v":0.52,"district_id":"palast"},{"slug":"silberkapelle","name":"Kapelle der Silbernen Rose","type":"Tempel","description":"Kleine Hofkapelle mit offenen Türen. Elysia-Flüstern unter kaiserlichem Stuck.","parent_id":"c1afce7e-5c4b-4fef-8654-818ef0534993","u":0.5,"v":0.4,"district_id":"palast"},{"slug":"nordtor","name":"Nordtor","type":"Tor","description":"Das nördliche Tor. Wer hier durchwill, hat entweder ein Wappen oder eine sehr gute Erklärung.","parent_id":"7a7b969e-cb22-4bc6-9356-4119442986fe","u":0.5,"v":0.1,"district_id":"adelsviertel"},{"slug":"blaue-gaerten","name":"Blaue Gärten","type":"Wohnhaus","description":"Heckenhöfe der Häuser. Nach Sonnenuntergang schließt das letzte Gitter.","parent_id":"7a7b969e-cb22-4bc6-9356-4119442986fe","u":0.4,"v":0.3,"district_id":"adelsviertel"},{"slug":"blauer-hirsch","name":"Taverne zum Blauen Hirsch","type":"Taverne","description":"Leises Haus, teure Krüge. Die Goldkelchen spielen hier für Adelsohren — und lauschen für das Haus der Seide.","parent_id":"7a7b969e-cb22-4bc6-9356-4119442986fe","u":0.58,"v":0.3,"district_id":"adelsviertel"},{"slug":"seidensalon","name":"Seidensalon der Nordhäuser","type":"Kontor","description":"Empfangszimmer mit Seidenbahnen. Das Haus der Seide verkauft hier Rang und Stoffe zugleich.","parent_id":"7a7b969e-cb22-4bc6-9356-4119442986fe","u":0.45,"v":0.22,"district_id":"adelsviertel"},{"slug":"tempel","name":"Goldene Tempelkuppel","type":"Tempel","description":"Die große Ostkuppel. Tagsüber Pilger, nachts eine Liturgie, die nicht im Kalender steht.","parent_id":"404d414c-7005-43b9-979a-077ea531177d","u":0.74,"v":0.42,"district_id":"tempelbezirk"},{"slug":"ostbrunnen","name":"Ostbrunnen","type":"Tempel","description":"Brunnen zwischen Palastgärten und Tempeln. Opfergaben verschwinden schneller als Wasser.","parent_id":"404d414c-7005-43b9-979a-077ea531177d","u":0.64,"v":0.34,"district_id":"tempelbezirk"},{"slug":"rose-hof","name":"Hof der Silbernen Rose","type":"Tempel","description":"Offener Kreuzgang mit weißen Rosen. Hier predigen Elysia-Anhänger gegen gezähltes Schicksal.","parent_id":"404d414c-7005-43b9-979a-077ea531177d","u":0.78,"v":0.36,"district_id":"tempelbezirk"},{"slug":"konklave-saal","name":"Saal der Ewigen Ordnung","type":"Tempel","description":"Geschlossener Chorraum. Chromus-Liturgie tickt in Kerzen und Zahlen.","parent_id":"404d414c-7005-43b9-979a-077ea531177d","u":0.7,"v":0.48,"district_id":"tempelbezirk"},{"slug":"observatorium","name":"Das magische Observatorium von Aurenfurt","type":"Akademie","description":"Kuppel und Sternenkammer der Magieakademie. Hier wird Vattrak gelehrt — und manches, das nicht im Lehrplan steht.","parent_id":"ac085f28-1167-4a29-9494-074f3ce61012","u":0.72,"v":0.48,"district_id":"akademieviertel"},{"slug":"schwertschule","name":"Die Schwertschule von Aurenfurt","type":"Akademie","description":"Militärakademie für Gardisten und Wachleute. Drillhöfe, Stangen und der Geruch von Öl und Disziplin.","parent_id":"ac085f28-1167-4a29-9494-074f3ce61012","u":0.68,"v":0.54,"district_id":"akademieviertel"},{"slug":"grosse-bibliothek","name":"Die Große Bibliothek von Aurenfurt","type":"Bibliothek","description":"Wissensspeicher zwischen den Konfessionen und der Akademie. Regale, Register — und Abschriften, die niemand ausleihen darf.","parent_id":"ac085f28-1167-4a29-9494-074f3ce61012","u":0.66,"v":0.5,"district_id":"akademieviertel"},{"slug":"schmiede","name":"Große Schmiede","type":"Schmiede","description":"Esse an der Südostmauer. Die Zunft kauft Erz, bevor die Garde Fragen stellt.","parent_id":"38c8a9fc-75cb-41fc-a8fc-4fa98996bf1a","u":0.7,"v":0.64,"district_id":"handwerkerviertel"},{"slug":"zunft","name":"Zunfthaus","type":"Kontor","description":"Schreibstube und Lager der Zünfte. Verträge gelten hier mehr als Wappen.","parent_id":"38c8a9fc-75cb-41fc-a8fc-4fa98996bf1a","u":0.6,"v":0.6,"district_id":"handwerkerviertel"},{"slug":"seidenkontor","name":"Kontor des Hauses der Seide","type":"Kontor","description":"Stand und Schreibstube am Handwerkermarkt. Hohe Gebühren, längere Reichweite bis in die blauen Salons.","parent_id":"38c8a9fc-75cb-41fc-a8fc-4fa98996bf1a","u":0.65,"v":0.56,"district_id":"handwerkerviertel"},{"slug":"gauklerbuehne","name":"Gauklerbühne der Goldkelchen","type":"Markt","description":"Bretter vor den Essen. Die Goldkelchen tanzen laut — und tragen leise Botschaften.","parent_id":"38c8a9fc-75cb-41fc-a8fc-4fa98996bf1a","u":0.55,"v":0.66,"district_id":"handwerkerviertel"},{"slug":"loewentor","name":"Löwentor","type":"Tor","description":"Zwei Löwen am Südausgang. Zoll und Garde teilen sich den Torbogen, die Schmuggler die Schatten.","parent_id":"a0a973ce-e497-48f9-87cf-75cad40e8ea3","u":0.5,"v":0.9,"district_id":"suedtor"},{"slug":"allee","name":"Taverne zur Allee","type":"Taverne","description":"An der grünen Prozessionsallee. Händler trinken, bevor sie das Tor nehmen.","parent_id":"a0a973ce-e497-48f9-87cf-75cad40e8ea3","u":0.54,"v":0.72,"district_id":"suedtor"},{"slug":"westmarkt","name":"Westmarkt","type":"Markt","description":"Stände vor den roten Dächern. Das Haus der Seide hält den teuersten Stand — Ware, Diebstahl und Gerüchte teilen sich das Tuch.","parent_id":"334d42e3-d15c-488a-9ae0-213ec914ba12","u":0.34,"v":0.62,"district_id":"unterstadt"},{"slug":"rote-laterne","name":"Taverne Rote Laterne","type":"Taverne","description":"Eng, laut, und die Wache kommt spät. Im Keller wird Malanthir nicht nur geflüstert.","parent_id":"334d42e3-d15c-488a-9ae0-213ec914ba12","u":0.31,"v":0.74,"district_id":"unterstadt"},{"slug":"malanthir-umschlagplatz","name":"Malanthir-Umschlagplatz","type":"Lager","description":"Verdeckter Hof des Roten Auges. Kisten ohne Siegel, Wege ohne Namen, Ware die niemand sehen soll.","parent_id":"334d42e3-d15c-488a-9ae0-213ec914ba12","u":0.28,"v":0.68,"district_id":"unterstadt"},{"slug":"wachenstube-rot","name":"Wachstube Rote Gassen","type":"Wache","description":"Dünn besetzte Stube der Stadtwachen. Unterwandert, überfordert — und trotzdem da.","parent_id":"334d42e3-d15c-488a-9ae0-213ec914ba12","u":0.38,"v":0.7,"district_id":"unterstadt"}],"npcs":[{"catalog_id":"npc-leader-bund-silberne-rose","location_slug":"rose-hof","name":"Priorin Elowen Silberblatt","title":"Hüterin der offenen Höfe","role":"Anführerin des Bundes der Silbernen Rose","race":"Elfin","alignment":"Neutral Good","description":"Elowen predigt im Hof der Silbernen Rose gegen gezähltes Schicksal und bietet Unterschlupf ohne Garde-Ohren.","appearance":"Weiße Rosen im Haar, schlichte Robe, warme Augen, eine silberne Brosche in Form einer Rose.","personality_traits":"Hoffnungsvoll, standhaft, weigert sich, Namen an die Garde zu geben.","gm_notes":"Rivalin des Konklaves; leichte Allianz zu Goldkelchen.\n\nGeheimnis (Spielleitung): Sie hat einmal einem Malanthir-Flüchtling Asyl gegeben — und schweigt, weil die Stadt ihn sonst henkte.","true_nature":"Elysia-Gläubige, die Ordnung als Käfig sieht.","hidden_agenda":"Konklave-Liturgie öffentlich entlarven und Hofkapelle stärken.","status":"Alive","narrative_hooks":[{"name":"Bruder Calen","role":"Heilkundiger","description":"Versorgt Verletzte ohne Fragen nach Kulten.","is_alive":true}],"check_results":[{"type":"Religion","dc":12,"result":"Ihre Worte gegen Chromus sind klar und gefährlich.","is_critical":false},{"type":"Insight","dc":14,"result":"Sie verheimlicht, wie viele sie bereits versteckt.","is_critical":false}],"for_city_simulation":true,"city_influence_tier":"authority_faction","city_axis_loyal_criminal":-2,"city_axis_greedy_altruist":3,"city_axis_pious_skeptic":-4,"city_axis_superstition_reason":-1,"city_deity":"Elysia","city_faction_id":"bund-silberne-rose","city_agenda":"Elysia-Hoffnung gegen Chromus-Zwang stellen.","city_event_deck":[]},{"catalog_id":"npc-leader-goldkelchen","location_slug":"gauklerbuehne","name":"Lirian Goldkehle","title":"Meister der Goldkelchen","role":"Anführer der Goldkelchen","race":"Mensch","alignment":"Chaotic Neutral","description":"Lirian tanzt und singt auf der Gauklerbühne, während seine Barden Gerüchte für das Haus der Seide sammeln.","appearance":"Goldene Ohrringe, bunte Weste, geschwärzte Fingernägel vom Schminken; Stimme trägt über drei Gassen.","personality_traits":"Charmant, witzig, immer eine Strophe voraus — und nie ganz ehrlich.","gm_notes":"Client des Hauses der Seide; meidet offene Konflikte mit dem Roten Auge.\n\nGeheimnis (Spielleitung): Er verkauft Namen von Flüchtlingen an das Haus der Seide — und behauptet, es sei nur Kunst.","true_nature":"Spitzelnetz unter Bardenkutte.","hidden_agenda":"Adelsohren füttern und Seidenhaus-Aufträge priorisieren.","status":"Alive","narrative_hooks":[{"name":"Mirena Flüsterton","role":"Bardin","description":"Spielt im Blauen Hirsch und lauscht Salon-Klatsch.","is_alive":true}],"check_results":[{"type":"Persuasion","dc":13,"result":"Er teilt ein harmloses Gerücht — und behält das brisante zurück.","is_critical":false},{"type":"Insight","dc":15,"result":"Seine Scherze lenken von Beobachtungen am Publikum ab.","is_critical":false}],"for_city_simulation":true,"city_influence_tier":"authority_faction","city_axis_loyal_criminal":1,"city_axis_greedy_altruist":-1,"city_axis_pious_skeptic":1,"city_axis_superstition_reason":0,"city_deity":null,"city_faction_id":"goldkelchen","city_agenda":"Informantennetz für Seide pflegen, ohne die Bühne zu verlieren.","city_event_deck":[]},{"catalog_id":"npc-leader-haeuser-des-nordens","location_slug":"goldkuppel","name":"Lady Isolde von Nordwacht","title":"Sprecherin der Nordhäuser","role":"Anführerin der Häuser des Nordens","race":"Mensch","alignment":"Lawful Neutral","description":"Isolde spricht unter der Goldenen Kuppel für die blauen Salons: Hofnähe, Gärten und Druck auf Garde und Markt.","appearance":"Hohe Frisur mit Silberkamm, kobaltblaues Gewand, kühle Augen, Stimme wie Glas.","personality_traits":"Elegant, unnahbar, denkt in Allianzen und Erblinien.","gm_notes":"Patron der Stadtwachen; Spannung zu beiden Tempelorden.\n\nGeheimnis (Spielleitung): Sie hat eine Chromus-Schriftrolle aus dem Tempelbezirk gestohlen, um das Konklave zu erpressen.","true_nature":"Machtpolitikerin hinter Höflichkeit.","hidden_agenda":"Tempelstreit als Hebel nutzen und Seidenhaus als Verbündeten halten.","status":"Alive","narrative_hooks":[{"name":"Kanzler Orwin","role":"Hofschreiber","description":"Fertigt Siegel — und vergisst auf Befehl Namen.","is_alive":true}],"check_results":[{"type":"Persuasion","dc":16,"result":"Sie gewährt Audienz — gegen Gefälligkeiten für die Salons.","is_critical":false},{"type":"History","dc":14,"result":"Ihr Haus hält alte Schulden über drei Generationen.","is_critical":false}],"for_city_simulation":true,"city_influence_tier":"apex_global","city_axis_loyal_criminal":-2,"city_axis_greedy_altruist":-2,"city_axis_pious_skeptic":1,"city_axis_superstition_reason":2,"city_deity":null,"city_faction_id":"haeuser-des-nordens","city_agenda":"Hofmacht und Gartenpolitik der Nordhäuser absichern.","city_event_deck":[]},{"catalog_id":"npc-leader-haus-der-seide","location_slug":"seidenkontor","name":"Seraphine Seidenhand","title":"Handelskonsulin","role":"Anführerin des Hauses der Seide","race":"Mensch","alignment":"Lawful Neutral","description":"Seraphine führt das Kontor am Handwerkermarkt: hohe Standgelder, längere Arme bis in die blauen Salons.","appearance":"Silbernes Haar streng gebunden, Seidenhandschuhe, ein Siegelring mit Spinnweben-Motiv.","personality_traits":"Höflich, unnachgiebig, spricht in Preisen und Fristen.","gm_notes":"Patron der Goldkelchen; Rivalität zum Zunftbund und Druck auf Adelskontakte.\n\nGeheimnis (Spielleitung): Sie lässt Westmarkt-Diebstähle zu, solange die Beute über Goldkelchen zurück an ihre Lager geht.","true_nature":"Macht durch Schulden und Standgebühren.","hidden_agenda":"Adelshäuser über Luxusware anbinden und Zunftverträge aushebeln.","status":"Alive","narrative_hooks":[{"name":"Torren Quill","role":"Buchhalter","description":"Kennt jede Standgebühr — und jede Ausnahme.","is_alive":true}],"check_results":[{"type":"Insight","dc":14,"result":"Jedes Lächeln ist eine Rechnung, die noch nicht gestellt wurde.","is_critical":false},{"type":"Investigation","dc":16,"result":"Doppelte Quittungen im Kontor belegen erzwungene „Schutzspenden“.","is_critical":false}],"for_city_simulation":true,"city_influence_tier":"authority_faction","city_axis_loyal_criminal":0,"city_axis_greedy_altruist":-4,"city_axis_pious_skeptic":2,"city_axis_superstition_reason":2,"city_deity":null,"city_faction_id":"haus-der-seide","city_agenda":"Handelsnetz und Adelsschulden ausbauen.","city_event_deck":[]},{"catalog_id":"npc-leader-konklave-ewige-ordnung","location_slug":"konklave-saal","name":"Numerus Kael Chronosiegel","title":"Erster Liturg","role":"Anführer des Konklaves der Ewigen Ordnung","race":"Mensch","alignment":"Lawful Evil","description":"Kael leitet die Chromus-Liturgie im Saal der Ewigen Ordnung: Kerzen, Zahlen, Zwang auf den Palast.","appearance":"Kahle Schädelhaut mit goldenen Zahlentätowierungen, schwere Kettenrobe, metronomische Gesten.","personality_traits":"Kalt, präzise, hält Mitgefühl für Rechenfehler.","gm_notes":"Rivalität zur Silbernen Rose; Allianz zu Teilen der Stadtwache.\n\nGeheimnis (Sp