rd.","is_critical":false}],"for_city_simulation":true,"city_influence_tier":"authority_faction","city_axis_loyal_criminal":-1,"city_axis_greedy_altruist":1,"city_axis_pious_skeptic":2,"city_axis_superstition_reason":4,"city_deity":null,"city_faction_id":"zirkel-observatorium","city_agenda":"Akademieautonomie und weiße Magie gegen Kultzwang schützen.","city_event_deck":[]},{"catalog_id":"npc-leader-zunftbund","location_slug":"zunft","name":"Meisterin Greta Hammerklang","title":"Zunftvögtin","role":"Anführerin des Zunftbunds Aurenfurt","race":"Zwergin","alignment":"Lawful Neutral","description":"Greta führt das Zunfthaus: Verträge wiegen mehr als Wappen, Essen und Kontore halten zusammen.","appearance":"Rußige Schürze über guter Wolle, Hammeramulett, kurze graue Zöpfe, feste Handschläge.","personality_traits":"Direkt, fair unter Zünftigen, misstrauisch gegen Adel und Seide.","gm_notes":"Spannung zu Haus der Seide und Stadtwachen; Rivalität zu Nordhäusern.\n\nGeheimnis (Spielleitung): Sie deckt einen Schmuggel von Zunftstahl an das Rote Auge — gegen Schutz der Essen vor Brandstiftung.","true_nature":"Pragmatikerin, die Unabhängigkeit der Handwerker verteidigt.","hidden_agenda":"Seidenhaus-Gebühren brechen und Hofprivilegien abwehren.","status":"Alive","narrative_hooks":[{"name":"Joran Esse","role":"Schmiedegeselle","description":"Kennt jede Lieferung Erz vor der Garde.","is_alive":true}],"check_results":[{"type":"Persuasion","dc":13,"result":"Sie handelt hart, aber hält Wort, wenn gesiegelt ist.","is_critical":false},{"type":"Investigation","dc":14,"result":"Zunftsiegel auf Dokumenten entlarven gefälschte Seidenhaus-Quittungen.","is_critical":false}],"for_city_simulation":true,"city_influence_tier":"authority_faction","city_axis_loyal_criminal":-1,"city_axis_greedy_altruist":-2,"city_axis_pious_skeptic":1,"city_axis_superstition_reason":2,"city_deity":null,"city_faction_id":"zunftbund","city_agenda":"Zunftautonomie und faire Preise gegen Seidennetz.","city_event_deck":