nger.","personality_traits":"Laut, geizig, immer im Handel.","gm_notes":"Seraphines Arm in der Unterstadt; zahlt Schutz an Vespera.\n\nGeheimnis (Spielleitung): Sie lässt Diebe stehlen und kauft die Beute billig zurück — mit Vesperas Segen.","true_nature":"Wucherin mit Marktprivileg.","hidden_agenda":"Preise und Gerüchte steuern.","status":"Alive","narrative_hooks":[{"name":null,"role":"Dieb","description":"Arbeitet für und gegen Nessa.","is_alive":true}],"check_results":[{"type":"Persuasion","dc":13,"result":"Sie handelt, solange man zahlt und schweigt.","is_critical":false},{"type":"Investigation","dc":14,"result":"Gewichte sind manipuliert.","is_critical":false}],"for_city_simulation":true,"city_influence_tier":"regional_economy","city_axis_loyal_criminal":0,"city_axis_greedy_altruist":-4,"city_axis_pious_skeptic":2,"city_axis_superstition_reason":2,"city_deity":null,"city_faction_id":"haus-der-seide","city_agenda":"Markt und Seidenanteil sichern.","city_event_deck":[]}]}$aurenfurt$::jsonb as doc
),
buildings as (
  select *
  from jsonb_to_recordset((select doc -> 'buildings' from seed)) as b(
    slug text,
    name text,
    type text,
    description text,
    parent_id uuid,
    u double precision,
    v double precision,
    district_id text
  )
),
tagged as (
  update public.locations as loc
  set map_building_id = b.slug
  from buildings b
  where loc.world_id = '689a0f11-7aa3-440b-9527-c6da0a84aebb'::uuid
    and loc.parent_location_id = b.parent_id
    and loc.name = b.name
    and (loc.map_building_id is null or loc.map_building_id = b.slug)
  returning loc.id
),
missing as (
  select
    b.*,
    md5('aurenfurt-building:' || b.slug)::uuid as new_id
  from buildings b
  where not exists (
    select 1
    from public.locations loc
    where loc.world_id = '689a0f11-7aa3-440b-9527-c6da0a84aebb'::uuid
      and (
        loc.map_building_id = b.slug
        or (loc.parent_location_id = b.parent_id and loc.name = b.name)
      )
  )
),
inserted_lore as (
  insert into public.world_lore (
    id, world_id, name, type, parent_id, description, image_url, is_revealed
  )
  select
    m.new_id,
    '689a0f11-7aa3-440b-9527-c6da0a84aebb'::uuid,
    m.name,
    m.type,
    m.parent_id,
    m.description,
    '/images/lore/ort-platzhalter.png',
    false
  from missing m
  on conflict (id) do nothing
  returning id
),
inserted_locations as (
  insert into public.locations (
    id,
    world_id,
    name,
    type,
    description,
    image_url,
    parent_location_id,
    map_u,
    map_v,
    map_district_id,
    map_building_id,
    created_via_map_editor
  )
  select
    m.new_id,
    '689a0f11-7aa3-440b-9527-c6da0a84aebb'::uuid,
    m.name,
    m.type,
    m.description,
    '/images/lore/ort-platzhalter.png',
    m.parent_id,
    m.u,
    m.v,
    m.district_id,
    m.slug,
    false
  from missing m
  on conflict (id) do nothing
  returning id
)
update public.locations as loc
set map_building_id = b.slug
from buildings b
where loc.world_id = '689a0f11-7aa3-440b-9527-c6da0a84aebb'::uuid
  and loc.parent_location_id = b.parent_id
  and loc.name = b.name
  and loc.map_building_id is null
  and (select count(*) from tagged) >= 0
  and (select count(*) from inserted_lore) >= 0
  and (select count(*) from inserted_locations) >= 0;

